import React, { useState, useRef } from "react";
import './account.css';
import NavBar from "../Components/NavBar"; 
import Footer from "../Components/Footer";
import { createUserWithEmailAndPassword, signInWithEmailAndPassword } from "firebase/auth";
import { auth, db } from "../firebase";
import { useNavigate } from "react-router-dom";
import { doc, setDoc } from "firebase/firestore";

export default function Account() {
  const [signUpData, setSignUpData] = useState({
    username: "",
    email: "",
    whatsapp: "",    // new whatsapp field
    password: "",
    confirmPassword: ""
  });
  const [signInData, setSignInData] = useState({
    emailOrUsername: "",
    password: ""
  });
  const [error, setError] = useState("");
  const checkboxRef = useRef(null);
  const navigate = useNavigate();

  const handleSignUpChange = (e) => {
    setSignUpData({...signUpData, [e.target.name]: e.target.value});
  };

  const handleSignInChange = (e) => {
    setSignInData({...signInData, [e.target.name]: e.target.value});
  };

  const handleSignUp = async (e) => {
    e.preventDefault();
    setError("");
    if (signUpData.password !== signUpData.confirmPassword) {
      setError("Passwords do not match.");
      return;
    }
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, signUpData.email, signUpData.password);
      const user = userCredential.user;

      // Save additional user data like username and whatsapp in Firestore
      await setDoc(doc(db, "users", user.uid), {
        username: signUpData.username,
        email: signUpData.email,
        whatsapp: signUpData.whatsapp
      });

      alert("Account created successfully!");
      if (checkboxRef.current) {
        checkboxRef.current.checked = true;
      }
      setSignUpData({
        username: "",
        email: "",
        whatsapp: "",
        password: "",
        confirmPassword: ""
      });
    } catch (err) {
      console.error("Firebase sign up error:", err);
      setError(err.message);
    }
  };

  const handleSignIn = async (e) => {
    e.preventDefault();
    setError("");
    try {
      const userCredential = await signInWithEmailAndPassword(auth, signInData.emailOrUsername, signInData.password);
      alert("Logged in successfully!");
      if (userCredential.user.email === "yasasmigunasinghe@gmail.com") {
        navigate("/admin");
      } else {
        navigate("/account"); // Replace with user home or dashboard if needed
      }
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <>
      <NavBar />
      <div className="acc-page">
        <section className="account">
          <input type="checkbox" id="check" aria-hidden="true" ref={checkboxRef} />

          <div className="signUp">
            <form onSubmit={handleSignUp}>
              <label htmlFor="check" aria-hidden="true" className="signup">SignUp</label>
              <input type="text" name="username" placeholder="User Name" required value={signUpData.username} onChange={handleSignUpChange} />
              <input type="email" name="email" placeholder="Email" required value={signInData.emailOrUsername} onChange={handleSignInChange} />

              <input type="text" name="whatsapp" placeholder="WhatsApp Number" required value={signUpData.whatsapp} onChange={handleSignUpChange} />  {/* New field */}
              <input type="password" name="password" placeholder="Password" required value={signUpData.password} onChange={handleSignUpChange} />
              <input type="password" name="confirmPassword" placeholder="Confirm Password" required value={signUpData.confirmPassword} onChange={handleSignUpChange} />
              <button type="submit">Sign Up</button>
              {error && <p style={{color:"yellow", textAlign:"center"}}>{error}</p>}
            </form>
          </div>

          <div className="signIn">
            <form onSubmit={handleSignIn}>
              <label htmlFor="check" aria-hidden="true">SignIn</label>
              <input type="email" name="emailOrUsername" placeholder="Email or User Name" id="username" required value={signInData.emailOrUsername} onChange={handleSignInChange} />
              <input type="password" name="password" placeholder="Password" id="password" required value={signInData.password} onChange={handleSignInChange} />
              <button type="submit">Sign In</button>
              <p><a href="#">Forget account?</a></p>
              {error && <p style={{color:"yellow", textAlign:"center"}}>{error}</p>}
            </form>
          </div>
        </section>
      </div>
      <Footer />
    </>
  );
}
